        var record=instance==null?null:instance(actor.server,instance);if(instance!=null&&(record==null||!record.source().equals(source)||!record.ownership().equals("team")||!teamKey(record).equals(key)||!permitted(actor,policy,record,"managers")))throw new JEDDefinitionException("Instance delegation is not permitted");
